var n=`1083-bicol-express`;var t=`world-1083`;var s=`PH`;var r=`southeast-asia`;var o=4;var a=68;var l={en:`Bicol Express`,ua:`Бікол експрес`};var u={en:`Bicol Express is a dish from Philippines prepared with garlic, yellow onion, pork belly, coconut milk. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Бікол експрес, страва кухні країни Філіппіни, яку готують із таких продуктів: часник, жовта цибуля, свиняча грудинка, кокосове молоко. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var d=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`garlic`,5,`clove`],[`yellow-onion`,180,`g`],[`ground-ginger`,30,`g`],[`canola-oil`,40,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 45 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 45 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:45,i:[[`pork-belly`,850,`g`],[`coconut-milk`,700,`ml`],[`shrimp-paste`,50,`g`],[`bird-s-eye-chili`,3,`pcs`]]},{en:`Continue simmering the sauce from the previous step uncovered until concentrated and thick enough to coat the ingredients.`,ua:`Продовжуйте виварювати соус із попереднього етапу без кришки, доки він загусне та вкриватиме складники.`,t:[`reducing-sauce`],m:12,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`serrano-pepper`,1,`pcs`]]}];var g={slug:n,id:t,country:`PH`,region:r,servings:4,minutes:68,title:l,text:u,steps:d};export{s as country,g as default,t as id,a as minutes,r as region,o as servings,n as slug,d as steps,u as text,l as title};